#[derive(Debug)]
enum DateTime64 {
    Nat,
    Valid(u64),
}

fn isnat(x: Vec<DateTime64>) -> Vec<bool> {
    x.into_iter().map(|dt| match dt {
        DateTime64::Nat => true,
        DateTime64::Valid(_) => false,
    }).collect()
}

fn main() {
    // Example usage
    let input = vec![
        DateTime64::Nat,
        DateTime64::Valid(1622548800000),
        DateTime64::Nat,
        DateTime64::Valid(1622548800001),
    ];
    
    let result = isnat(input);
    println!("{:?}", result); // Output: [true, false, true, false]
}